#include "mspa/decision/decision.hpp"
#include "mspa/psychology/learning.hpp"
#include "mspa/psychology/personality.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {namespace{float clamp11(float x){return std::clamp(x,-1.0f,1.0f);}float curve_eval(const ConsiderationSchema&s,float x){if(s.curve.empty())return x;if(x<=s.curve.front().x)return s.curve.front().y;if(x>=s.curve.back().x)return s.curve.back().y;auto hi=std::upper_bound(s.curve.begin(),s.curve.end(),x,[](float v,const CurvePointData&p){return v<p.x;});auto lo=hi-1;float t=(x-lo->x)/(hi->x-lo->x);return lo->y+t*(hi->y-lo->y);}void add(CandidateScore&r,const std::string&n,float raw,float w){r.considerations.push_back({n,raw,w});r.utility+=w;}}
CandidateScore UtilityComposer::score(const ActionOption&o)const{AgentPsychState a{};return score(o,a,{},RegistrySnapshot{});}CandidateScore UtilityComposer::score(const ActionOption&o,const AgentPsychState&a,const DecisionContext&c)const{return score(o,a,c,RegistrySnapshot{});}CandidateScore UtilityComposer::score(const ActionOption&o,const AgentPsychState&a,const DecisionContext&c,const RegistrySnapshot&r)const{CandidateScore out{};out.action=o.instance;const auto pd=PersonalitySystem{}.derive(a.personality);const float fear=[&](){float x=0;for(const auto&e:a.emotions)if(e.kind==BasicEmotion::Fear||e.kind==BasicEmotion::Anxiety)x=std::max(x,e.intensity);return x;}();add(out,"cost",o.cost,-std::max(0.0f,o.cost));float risk_weight=1.15f-0.65f*a.personality.boldness+0.45f*fear;add(out,"risk",o.risk,-std::max(0.0f,o.risk)*risk_weight);add(out,"progress",o.progress,std::clamp(o.progress,0.0f,1.0f)*(0.4f+0.6f*a.personality.persistence));add(out,"novelty",o.novelty,std::clamp(o.novelty,0.0f,1.0f)*(pd.exploration-0.35f));add(out,"social",o.social_exposure,std::clamp(o.social_exposure,0.0f,1.0f)*(a.personality.sociability-0.35f));for(const auto&e:o.expected_effects){float w=0;switch(e.channel){case EffectChannel::Need:for(const auto&n:c.needs)if(n.concept_id==e.concept_id)w+=n.pressure*e.magnitude;break;case EffectChannel::Value:for(const auto&v:a.values)if(v.concept_id==e.concept_id)w+=v.intensity*e.magnitude;break;case EffectChannel::Goal:for(const auto&g:a.goals)if(g.concept_id==e.concept_id&&g.active())w+=g.priority*(0.5f+0.5f*g.commitment)*e.magnitude;break;case EffectChannel::Relationship:if(e.target.valid()){auto it=std::find_if(a.relationships.begin(),a.relationships.end(),[&](const auto&x){return x.other==e.target;});if(it!=a.relationships.end())w+=(0.4f*it->affection+0.25f*it->trust+0.2f*it->respect+0.15f*it->familiarity)*e.magnitude*(0.5f+0.5f*a.personality.empathy);}break;case EffectChannel::Emotion:w+=e.magnitude*(0.5f+0.5f*a.mood.valence);break;case EffectChannel::Generic:w+=e.magnitude;break;}add(out,"effect",e.magnitude,clamp11(w));}const float expected=LearningSystem{}.expected_success(a,o.type,o.context_tags);add(out,"learned_success",expected,(expected-0.5f)*(0.7f+0.3f*(1.0f-a.personality.curiosity)));if(const auto*schema=r.find_action(o.type)){for(const auto&id:schema->considerations){const auto*def=r.find_consideration(id);if(!def)continue;float raw=0;auto it=o.signals.find(id);if(it!=o.signals.end())raw=it->second;else{auto jt=c.signals.find(id);if(jt!=c.signals.end())raw=jt->second;}float weighted=curve_eval(*def,raw)*def->weight;add(out,"pack:"+id,raw,weighted);}}return out;}
}
